runtime_probes.owned_probe_qml:
import QtQuick
import QtTest
import "<checkout>/src/steamzero/ui/qml"
Item {
    id: root
    width: 640; height: 360
    property var results: []
    readonly property url missingMedia: Qt.resolvedUrl("deliberately-absent-owned-fixture.png")
    function find(item, propertyName, value) {
        if (item[propertyName] !== undefined && String(item[propertyName]) === value) return item
        const children = item.children || []
        for (let i=0;i<children.length;i++) {
            const found=find(children[i],propertyName,value)
            if (found) return found
        }
        return null
    }
    SceneEsdeView { id: scene; anchors.fill: parent; viewData: ({id:"probe",elements:[]}) }
    TestCase {
        name: "ImportedSceneParityAudit"
        when: windowShown
        function test_01_requested_color_alpha_and_nonvisual_kinds() {
            const request=new XMLHttpRequest()
            request.open("GET",Qt.resolvedUrl("runtime-styled-scene.json"),false)
            request.send()
            scene.viewData=JSON.parse(request.responseText).views[0]
            tryCompare(scene,"drawnCount",1)
            let text=null
            tryVerify(function(){text=root.find(scene,"text","owned parity fixture");return text!==null})
            const result={case:"retrofe-imported-style-and-kinds",requestedColor:"#ff0000",
                observedColor:text.color.toString(),requestedAlpha:0,
                observedLoaderOpacity:text.parent.opacity,drawnCount:scene.drawnCount,
                notDrawn:scene.notDrawn,fullParity:false}
            verify(result.observedColor !== result.requestedColor)
            verify(result.observedLoaderOpacity > 0)
            verify(scene.notDrawn.some(function(row){return row.kind==="menu"}))
            verify(scene.notDrawn.some(function(row){return row.kind==="sound"}))
            root.results.push(result)
        }
        function test_02_unreadable_media_feedback() {
            scene.viewData={id:"broken-media",elements:[{id:"image-0",kind:"image",
                source:root.missingMedia.toString(),
                layout:{x:0.1,y:0.1,width:0.6,height:0.6}}]}
            let picture=null
            tryVerify(function(){
                picture=root.find(scene,"source",root.missingMedia.toString())
                return picture!==null && picture.status===Image.Error
            })
            const fallback=root.find(scene,"text","Arte indisponível")
            verify(fallback!==null)
            const result={case:"invalid-media-feedback",imageStatus:picture.status,
                drawnCount:scene.drawnCount,fallbackVisible:fallback.parent.visible,
                fullParity:false}
            compare(result.drawnCount,1)
            compare(result.fallbackVisible,false)
            root.results.push(result)
        }
        function cleanupTestCase(){console.log("AUDIT_RUNTIME="+JSON.stringify(root.results))}
    }
}
